<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

trait UserInvitationTenantAccessor
{
    private UserInvitationTenantVO $_tenant;
    public function getTenant(): TenantRef
    {
        return $this->_tenant->value();
    }
    public function tenant(): UserInvitationTenantVO
    {
        return $this->_tenant;
    }
    public function isTenantChanged(?self $original = null): bool
    {
        return !$this->_tenant->equals($original?->_tenant);
    }
    public function withTenant(UserInvitationTenantVO|TenantRef $tenant): self
    {
        $copy = clone $this;
        $copy->_tenant = UserInvitationTenantVO::from($tenant);
        return $copy;
    }
}
